import React from "react";
import { motion } from "framer-motion";

const Contact = () => {
  const contactInfo = [
    { label: "Email", value: "mallikarjunbendawade9972@gmail.com", link: "mailto:mallikarjunbendawade9972@gmail.com" },
    { label: "Phone", value: "+91 8546964951", link: "tel:+918546964951" },
    { label: "Location", value: "Bengaluru, India", link: "#" },
  ];

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1,
      },
    },
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: { duration: 0.6 },
    },
  };

  return (
    <motion.section
      className="section contact"
      id="contact"
      variants={containerVariants}
      initial="hidden"
      whileInView="visible"
      viewport={{ once: true, margin: "-100px" }}
    >
      <motion.h2 variants={itemVariants}>Get In Touch</motion.h2>

      <motion.p className="contact-subtitle" variants={itemVariants}>
        I'm always interested in hearing about new projects and opportunities.
      </motion.p>

      <motion.div className="contact-content" variants={containerVariants}>
        <div className="contact-info">
          {contactInfo.map((item, index) => (
            <motion.a
              key={index}
              href={item.link}
              className="contact-item"
              variants={itemVariants}
              whileHover={{ x: 10 }}
            >
              <span className="contact-label">{item.label}</span>
              <span className="contact-value">{item.value}</span>
            </motion.a>
          ))}
        </div>

        <motion.div className="contact-cta" variants={itemVariants}>
          <motion.a
            href="mailto:mallikarjunbendawade9972@gmail.com"
            className="btn btn-primary"
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
          >
            Send Me an Email
          </motion.a>
        </motion.div>
      </motion.div>
    </motion.section>
  );
};

export default Contact;
